import { service, confirmDialog, alertDialog } from './desktop.js';

let data={cars:[],entries:[],categories:[],addresses:[]};const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}),sum=(rows,k)=>rows.filter(e=>e.kind===k).reduce((s,e)=>s+e.cents,0);
function vehicleLabel(c){return c?.plate||c?.name||'未填写车牌'}
function options(){return data.cars.map(c=>`<option value="${c.id}">${esc(vehicleLabel(c))}</option>`).join('')}
function render(){let income=sum(vehicleOverviewEntries(),'收入'),expense=sum(vehicleOverviewEntries(),'支出');$('stats').innerHTML=[['车辆总数',data.cars.length+' 台'],['累计收入','¥ '+money(income)],['累计支出','¥ '+money(expense)],['收支差额','¥ '+money(income-expense)]].map(([k,v])=>`<div class="stat"><span class="muted">${k}</span><strong>${v}</strong></div>`).join('');let q=$('search').value.toLowerCase();$('cars').innerHTML=data.cars.filter(c=>(ledgerVehicleSelection===null||ledgerVehicleSelection.has(String(c.id)))&&[c.name,c.plate,c.vin].join(' ').toLowerCase().includes(q)).map(c=>{let rows=vehicleOverviewEntries().filter(e=>e.car_id===c.id),i=sum(rows,'收入'),o=sum(rows,'支出');return `<tr><td><a class="vehicle-link" href="#/cars/${c.id}"><b>${esc(vehicleLabel(c))}</b></a></td><td>${esc(c.vin)||'—'}</td><td>+${money(i)}</td><td>−${money(o)}</td><td>${money(i-o)}</td><td><button onclick="carForm(${c.id})">编辑</button> <button onclick="entryForm(${c.id})">记账</button></td></tr>`}).join('')||'<tr><td colspan="6" class="muted">还没有车辆，点击「新增车辆」开始。</td></tr>';let rows=data.entries.filter(e=>(!$('filter').value||e.car_id==$('filter').value)&&(!$('start').value||e.date>=$('start').value)&&(!$('end').value||e.date<=$('end').value)).sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id);$('subtotal').textContent=`当前筛选 ${rows.length} 笔 · 收入 ¥${money(sum(rows,'收入'))} · 支出 ¥${money(sum(rows,'支出'))}`;$('entries').innerHTML=rows.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(vehicleLabel(data.cars.find(c=>c.id===e.car_id)))}</td><td>${esc(e.kind)}</td><td>${esc(e.category)}</td><td>${money(e.cents)}</td><td>${esc(e.start_address)||'未记录'} → ${esc(e.end_address)||'未记录'}</td><td>${esc(e.party)}<br><small>${esc(e.note)}</small></td></tr>`).join('')||'<tr><td colspan="7" class="muted">暂无账目。</td></tr>'}
function field(label,name,value='',required=false,type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0.01" step="0.01" max="999999999"':''}></label>`}
function carForm(id){let c=data.cars.find(c=>c.id===id)||{};openForm(id?'编辑车辆':'录入汽车',field('车牌 *','plate',c.plate,true)+field('车架号 VIN','vin',c.vin)+field('备注','note',c.note),'/api/cars',id)}
function syncCategories(){let kind=$('form').elements.kind.value;$('form').elements.category.innerHTML=data.categories.filter(c=>c.active&&c.kind===kind).map(c=>`<option>${esc(c.name)}</option>`).join('')||'<option value="">请先到类型管理添加类型</option>';syncRoute()}
function renderCategories(){document.querySelector('main').innerHTML='<section><div class="toolbar"><h2>收支类型管理</h2><button onclick="categoryForm()">＋ 新增类型</button></div><p class="muted">修改和删除仅影响后续记账，历史账目保留原名称。新增同名类型可恢复使用。</p><table><thead><tr><th>收支</th><th>类型名称</th><th>路线要求</th><th>操作</th></tr></thead><tbody>'+data.categories.filter(c=>c.active).map(c=>`<tr><td>${esc(c.kind)}</td><td>${esc(c.name)}</td><td>${c.requires_route?'必填':'选填'}</td><td><button onclick="categoryForm(${c.id})">修改</button> <button onclick="removeCategory(${c.id})">删除</button></td></tr>`).join('')+'</tbody></table></section>'}
function categoryForm(id,kind='支出'){let c=data.categories.find(c=>c.id===id)||{};kind=c.kind||kind;openForm((id?'修改':'新增')+kind+'类型',`<input type="hidden" name="kind" value="${kind}"><p class="help">所属方向：${kind}</p>`+field('类型名称 *','name',c.name,true)+`<label><input style="width:auto" type="checkbox" name="requires_route" ${c.requires_route?'checked':''}> 路线必填</label>`,'/api/categories',id)}
async function removeCategory(id){if(!await confirmDialog('删除此类型？历史账目会保留。'))return;try{let r=await service.request('/api/categories/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(!r.ok)throw Error();await load()}catch{await alertDialog('删除失败，请重试')}}
function addressLabel(a){return a.name+(a.detail?' / '+a.detail:'')}
function renderAddresses(){document.querySelector('main').innerHTML='<p id="message" role="status"></p><section><div class="toolbar"><h2>地址管理</h2><input id="addressSearch" placeholder="搜索名称或详细地址" oninput="renderAddressRows()"><button onclick="addressForm()">＋ 新增地址</button></div><p class="muted">地址可用于起点和终点。修改或删除不影响历史账目。</p><table><thead><tr><th>名称</th><th>详细地址</th><th>操作</th></tr></thead><tbody id="addressRows"></tbody></table></section>';renderAddressRows()}
function renderAddressRows(){let q=$('addressSearch').value.toLowerCase();$('addressRows').innerHTML=data.addresses.filter(a=>a.active&&addressLabel(a).toLowerCase().includes(q)).map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.detail)}</td><td><button onclick="addressForm(${a.id})">修改</button> <button onclick="removeAddress(${a.id})">删除</button></td></tr>`).join('')||'<tr><td colspan="3">暂无地址，请新增地址。</td></tr>'}
function addressForm(id){let a=data.addresses.find(a=>a.id===id)||{};openForm(id?'修改地址':'新增地址',field('地址名称 *','name',a.name,true)+field('详细地址','detail',a.detail),'/api/addresses',id)}
async function removeAddress(id){if(!await confirmDialog('删除此地址？历史账目保留原地址。'))return;try{let r=await service.request('/api/addresses/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});let result=await r.json();if(!r.ok)throw Error(result.error);await load()}catch(e){$('message').textContent=e.message||'删除失败，请重试'}}

// Shared page state and accessible feedback.
let initialForm='',subview=null,toastTimer,returnFocus=null;
const page=location.hash.slice(1)||'/cars';
const detailMatch=page.match(/^\/cars\/(\d+)$/),detailId=detailMatch?Number(detailMatch[1]):null;
document.querySelectorAll('aside nav a').forEach(a=>{if((a.getAttribute('href')==='#'+page||((detailId!==null||page==='/')&&a.getAttribute('href')==='#/cars'))){a.classList.add('active');a.setAttribute('aria-current','page')}});
$('pageTitle').textContent=page==='/addresses'?'地址管理':page==='/categories'?'收支类型':page==='/entries'?'收支账目':'车辆管理';
if(page==='/categories'||page==='/addresses')document.querySelector('.header-actions').replaceChildren();
function notify(message){const toast=$('toast');clearTimeout(toastTimer);toast.textContent=message;if(toast.matches(':popover-open'))toast.hidePopover();toast.showPopover();toastTimer=setTimeout(()=>{toast.hidePopover();toast.textContent=''},3500)}
function formState(){return JSON.stringify([...new FormData($('form')).entries()])}
async function requestClose(){if($('save').disabled)return;if(formState()!==initialForm&&!await confirmDialog('还有未保存的内容，确定放弃修改？'))return;if(subview){restoreEntry();return}$('modal').close();returnFocus?.focus()}
$('modal').addEventListener('cancel',e=>{e.preventDefault();requestClose()});
function refreshTables(){document.querySelectorAll('table').forEach(t=>{let headers=[...t.querySelectorAll('th')].map(x=>x.textContent);t.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((cell,i)=>{if(cell.colSpan===1)cell.dataset.label=headers[i]||''}));});document.querySelectorAll('td button').forEach(b=>{if(['编辑','记账','修改'].includes(b.textContent.trim()))b.classList.add('row-action');if(['删除','移除常用'].includes(b.textContent.trim()))b.classList.add('danger')});document.querySelectorAll('#entries tr').forEach(tr=>{let cells=tr.cells;if(cells.length<5)return;let income=cells[2].textContent==='收入';cells[2].innerHTML=`<span class="badge ${income?'income':'expense'}">${income?'收入':'支出'}</span>`;cells[4].classList.add('amount',income?'income':'expense');cells[4].textContent=(income?'+':'−')+cells[4].textContent});document.querySelectorAll('#cars tr').forEach(tr=>{if(tr.cells.length<6)return;[2,3,4].forEach(i=>tr.cells[i].classList.add('amount'));tr.cells[2].classList.add('income');tr.cells[3].classList.add('expense')})}
const originalRender=render;render=function(){originalRender();if(!$('cars').querySelector('button')&&$('search').value)$('cars').innerHTML='<tr><td colspan="6" class="empty">没有匹配的车辆，请调整搜索关键词。</td></tr>';if(!data.entries.length)$('entries').innerHTML='<tr><td colspan="7" class="empty">暂无账目，点击「记一笔账」开始记录。</td></tr>';else if(!$('entries').querySelector('td:nth-child(2)'))$('entries').innerHTML='<tr><td colspan="7" class="empty">没有符合筛选条件的账目，请调整条件或清空筛选。</td></tr>';refreshTables()};
renderCategories=function(){document.querySelector('main').innerHTML='<p id="message" role="status"></p><p class="help">收入与支出类型分别维护。修改或删除不影响历史账目。</p><div class="category-lists">'+['收入','支出'].map((kind,i)=>`<section id="category-group-${i}"><div class="toolbar"><h2 class="${i?'expense':'income'}">${kind}类型</h2><button onclick="categoryForm(null,'${kind}')">＋ 新增${kind}类型</button><input aria-label="搜索${kind}类型" placeholder="搜索${kind}类型" oninput="filterCategories(this.value,${i})"></div><table><thead><tr><th>类型名称</th><th>路线要求</th><th>操作</th></tr></thead><tbody>${data.categories.filter(c=>c.active&&c.kind===kind).map(c=>`<tr><td>${esc(c.name)}</td><td>${c.requires_route?'必填':'选填'}</td><td><button onclick="categoryForm(${c.id})">修改</button> <button onclick="removeCategory(${c.id})">删除</button></td></tr>`).join('')}</tbody></table><p class="category-empty help" ${data.categories.some(c=>c.active&&c.kind===kind)?'hidden':''}>暂无${kind}类型，可点击上方新增。</p></section>`).join('')+'</div>';refreshTables()};
function filterCategories(q,group){const section=$('category-group-'+group);let shown=0;section.querySelectorAll('tbody tr').forEach(r=>{r.hidden=!r.cells[0].textContent.toLowerCase().includes(q.toLowerCase());if(!r.hidden)shown++});const empty=section.querySelector('.category-empty');empty.hidden=shown>0;empty.textContent=q?'没有匹配的类型，请调整搜索关键词。':'暂无类型，可点击上方新增。'}

const originalAddresses=renderAddresses;renderAddresses=function(){originalAddresses();refreshTables()};
const originalAddressRows=renderAddressRows;renderAddressRows=function(){originalAddressRows();refreshTables()};
let vehicleProjectSelection=null;
let vehicleKindSelection=null;
const vehicleRouteSelection={start:null,end:null,party:null};
let ledgerVehicleSelection=null;
const projectKey=e=>JSON.stringify([e.kind,e.category]);
function clearFilters(){if(detailId!==null||page==='/entries'){if($('filter'))$('filter').value='';ledgerVehicleSelection=null;renderLedgerVehicleFilter();vehicleProjectSelection=null;vehicleKindSelection=null;vehicleRouteSelection.start=null;vehicleRouteSelection.end=null;vehicleRouteSelection.party=null;renderRouteFilters('party');renderRouteFilters('start');renderRouteFilters('end');renderKindFilters();renderProjectFilters();$('start').value='';$('end').value='';renderVehicleEntries();return}ledgerVehicleSelection=null;renderLedgerVehicleFilter();$('filter').value='';$('start').value='';$('end').value='';render()}
async function load(){try{let r=await service.request('/api/data');if(!r.ok)throw Error('读取失败');data=await r.json();if(page==='/entries'){renderAllLedger();return}if(detailId!==null){renderVehicleDetail();return}if(page==='/addresses'){renderAddresses();return}if(page==='/categories'){renderCategories();return}let prev=$('filter').value;$('filter').innerHTML='<option value="">全部车辆</option>'+options();$('filter').value=prev;render()}catch{let m=$('message');if(!m){document.querySelector('main').insertAdjacentHTML('afterbegin','<p id="message" role="alert"></p>');m=$('message')}m.innerHTML='读取失败，请检查服务。 <button class="secondary" onclick="load()">重试</button>'}}
function showFieldError(name,message){let input=$('form').elements[name];if(!input)return false;input.setAttribute('aria-invalid','true');let label=input.closest('label')||input.parentElement;let error=document.createElement('p');error.className='field-error';error.id='error-'+name;error.textContent=message;label.append(error);input.setAttribute('aria-describedby',error.id);return true}
function clearErrors(){$('form').querySelectorAll('.field-error').forEach(e=>e.remove());$('form').querySelectorAll('[aria-invalid]').forEach(e=>{e.removeAttribute('aria-invalid');e.removeAttribute('aria-describedby')});$('error').textContent=''}
function openForm(title,html,path,id){returnFocus=document.activeElement;$('title').textContent=title;$('fields').innerHTML=html;clearErrors();if(!$('modal').open)$('modal').showModal();initialForm=formState();$('fields').querySelector('input:not([type=hidden]),select,textarea')?.focus();$('save').textContent='保存';$('form').onsubmit=async e=>{e.preventDefault();if($('save').disabled)return;clearErrors();let f=$('form');let invalid=[...f.elements].find(x=>x.willValidate&&!x.checkValidity());if(invalid){showFieldError(invalid.name,invalid.validity.valueMissing?'请填写此项':invalid.validationMessage);invalid.focus();return}let d=Object.fromEntries(new FormData(f));if(id)d.id=id;if(path==='/api/categories')d.requires_route=f.elements.requires_route.checked;
if(path==='/api/entries'){for(let side of ['start','end']){let input=f.elements[side+'_address'];let edit=f.elements.id?data.entries.find(e=>e.id===Number(f.elements.id.value)):null;let a=data.addresses.find(a=>(a.active||(edit&&edit[side+'_address_id']===a.id))&&addressLabel(a)===input.value);if(input.value&&!a){showFieldError(input.name,'请从候选列表选择有效地址');input.focus();return}d[side+'_address_id']=a?.id||null}if(Boolean(d.start_address_id)!==Boolean(d.end_address_id)){let name=d.start_address_id?'end_address':'start_address';showFieldError(name,'请补齐起点和终点');f.elements[name].focus();return}}
$('save').disabled=true;$('save').textContent='保存中…';try{let r=await service.request(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});let result=await r.json();if(!r.ok)throw Error(result.error||'保存失败');if(subview){let res=await service.request('/api/data');if(!res.ok)throw Error('地址已保存，列表刷新失败，请重试刷新');data=await res.json();let a=data.addresses.find(a=>a.active&&a.name===d.name.trim());let side=subview.side;restoreEntry();if(a){$('form').elements[side+'_address'].value=addressLabel(a)}notify('地址已新增，可继续记账');return}$('modal').close();await load();notify('保存成功');returnFocus?.focus()}catch(error){let message=error instanceof TypeError?'网络连接失败，请检查服务后重试':error.message||'保存失败，请重试';$('error').textContent=message;let name=message.includes('车牌')?'plate':message.includes('名称')?'name':message.includes('金额')?'amount':message.includes('地址')||message.includes('起点')?'start_address':message.includes('类型')?'category':null;if(name&&showFieldError(name,message))f.elements[name]?.focus();else $('error').setAttribute('tabindex','-1'),$('error').focus()}finally{$('save').disabled=false;$('save').textContent='保存'}}}
function sectionFields(title,html){if(title==='运输路线')return `<fieldset><div class="route-section-heading"><span>运输路线</span><p id="routeHint" class="help"></p><button class="text-button" type="button" onclick="refreshAddresses()">刷新地址列表</button></div><div class="form-grid">${html}</div></fieldset>`;return `<fieldset><legend>${title}</legend><div class="form-grid">${html}</div></fieldset>`}
function entryForm(id){if(detailId!==null)id=detailId;if(!data.cars.length){carForm();notify('先新增一台车辆，即可开始记账');return}subview=null;let now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');openForm('记一笔账',sectionFields('基本信息',`<label>车辆 *<select name="car_id" required>${options()}</select></label>`+field('记账日期 *','date',today,true,'date'))+sectionFields('金额与类型','<div><label>收支方向</label><input type="hidden" name="kind" value="支出"><div class="segmented" role="group" aria-label="收支方向"><button type="button" data-kind="支出" onclick="setKind(\'支出\')">支出</button><button type="button" data-kind="收入" onclick="setKind(\'收入\')">收入</button></div></div><label>收支项目 *<select name="category" onchange="syncRoute()" required></select></label><label class="span-all">金额 *<div class="money-input"><input name="amount" type="number" required min="0.01" max="999999999" step="0.01" inputmode="decimal" placeholder="0.00"><span>元</span></div></label>')+sectionFields('运输路线',routeFields())+sectionFields('补充信息',field('往来方','party')+field('备注','note')),'/api/entries');if(id)$('form').elements.car_id.value=id;setKind('支出');initialForm=formState()}
function setKind(kind){$('form').elements.kind.value=kind;document.querySelectorAll('[data-kind]').forEach(b=>{let selected=b.dataset.kind===kind;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)});syncCategories()}
function routeFields(){return '<div class="route-pair span-all">'+['start','end'].map((side,i)=>`<label class="address-picker">${i?'终点':'起点'}<input role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${side}-list" name="${side}_address" placeholder="搜索名称或详细地址" autocomplete="off" oninput="suggest('${side}')" onfocus="suggest('${side}')" onkeydown="addressKey(event,'${side}')" onblur="hideSuggestions('${side}')"><div class="suggestions" id="${side}-list" role="listbox" hidden></div><button class="text-button" type="button" onclick="openRegion('${side}')">选择省 / 市 / 区县 / 乡镇</button></label>${i===0?'<button type="button" class="route-swap-icon" onclick="swapRoute()" title="交换起终点" aria-label="交换起终点"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 8h15m-4-4 4 4-4 4M20 16H5m4-4-4 4 4 4"/></svg></button>':''}`).join('')+'</div>'}
function syncRoute(){let f=$('form').elements,required=!!data.categories.find(c=>c.active&&c.kind===f.kind.value&&c.name===f.category.value)?.requires_route;for(let side of ['start','end']){let input=f[side+'_address'];const edit=f.id?data.entries.find(e=>e.id===Number(f.id.value)):null;const legacy=edit&&!edit.start_address_id&&!edit.end_address_id&&edit.kind===f.kind.value&&edit.category===f.category.value;input.required=required&&!legacy;input.setAttribute('aria-required',String(required))}$('routeHint').textContent=(required?'此项目路线必填':'路线选填，填写时须补齐起终点')+(data.addresses.some(a=>a.active)?'':' · 可从全国基础库选择地区')}
function suggest(side){let input=$('form').elements[side+'_address'],box=$(side+'-list'),q=input.value.toLowerCase();let matches=data.addresses.filter(a=>a.active&&addressLabel(a).toLowerCase().includes(q));box.innerHTML=matches.map(a=>`<button type="button" role="option" id="${side}-option-${a.id}" aria-selected="false" data-id="${a.id}" onmousedown="event.preventDefault()" onclick="chooseAddress('${side}',${a.id})">${esc(a.name)}<small>${esc(a.detail)||'未填写详细地址'}</small></button>`).join('')||'<p class="help" style="padding:10px">没有匹配的常用地区，请从下方行政区划选择。</p>';box.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant')}
function chooseAddress(side,id){let a=data.addresses.find(a=>a.id===id);$('form').elements[side+'_address'].value=addressLabel(a);$(side+'-list').hidden=true;$('form').elements[side+'_address'].setAttribute('aria-expanded','false');$('form').elements[side+'_address'].removeAttribute('aria-activedescendant')}
function hideSuggestions(side){$(side+'-list').hidden=true;$('form').elements[side+'_address'].setAttribute('aria-expanded','false')}
function addressKey(e,side){let input=e.target,box=$(side+'-list');if(e.key==='Escape'&&!box.hidden){e.preventDefault();e.stopPropagation();hideSuggestions(side);return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(box.hidden)suggest(side);let opts=[...box.querySelectorAll('[role=option]')];if(!opts.length)return;let i=opts.findIndex(o=>o.getAttribute('aria-selected')==='true');i=e.key==='ArrowDown'?(i+1)%opts.length:(i<=0?opts.length-1:i-1);opts.forEach((o,j)=>o.setAttribute('aria-selected',String(i===j)));input.setAttribute('aria-activedescendant',opts[i].id);opts[i].scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&!box.hidden){let selected=box.querySelector('[aria-selected=true]');if(selected){e.preventDefault();chooseAddress(side,Number(selected.dataset.id))}}}
function swapRoute(){let f=$('form').elements;[f.start_address.value,f.end_address.value]=[f.end_address.value,f.start_address.value];hideSuggestions('start');hideSuggestions('end')}
async function refreshAddresses(){try{let r=await service.request('/api/data');if(!r.ok)throw Error();data.addresses=(await r.json()).addresses;syncRoute();notify('地址列表已更新')}catch{$('error').textContent='地址刷新失败，请检查连接后重试'}}
function inlineAddress(side){let f=$('form');subview={side,html:$('fields').innerHTML,values:[...new FormData(f)].map(([k,v])=>[k,v]),submit:f.onsubmit,initial:initialForm,title:$('title').textContent};openForm('新增地址 · 返回后继续记账',field('地址名称 *','name','',true)+field('详细地址','detail'),'/api/addresses')}
function restoreEntry(){let saved=subview;subview=null;$('fields').innerHTML=saved.html;for(let [k,v] of saved.values){if($('form').elements[k])$('form').elements[k].value=v}$('title').textContent=saved.title;$('form').onsubmit=saved.submit;initialForm=saved.initial;clearErrors();document.querySelectorAll('.suggestions').forEach(e=>e.hidden=true);document.querySelectorAll('[role=combobox]').forEach(e=>e.setAttribute('aria-expanded','false'));syncRoute()}

function renderVehicleDetail(){
 const car=data.cars.find(c=>c.id===detailId);
 $('pageTitle').textContent=car?vehicleLabel(car):'车辆不存在';
 document.querySelector('.header-actions').innerHTML='<a class="link secondary" href="#/cars">返回车辆列表</a>'+(car?'<button onclick="entryForm()">＋ 记一笔账</button>':'');
 if(!car){document.querySelector('main').innerHTML='<section class="empty"><h2>车辆不存在</h2><p>这台车辆不存在，请返回车辆列表选择。</p><a href="#/cars">返回车辆列表</a></section>';return}
 let all=ledgerScope(),income=sum(all,'收入'),expense=sum(all,'支出');
 const from=$('start')?.value||'',to=$('end')?.value||'';
 document.querySelector('main').innerHTML='<p id="message" role="status"></p><section class="vehicle-profile"><h2>'+esc(vehicleLabel(car))+'</h2><div class="profile-grid"><div><small>车牌</small><strong>'+esc(car.plate||'未填写')+'</strong></div><div><small>车架号 VIN</small><strong>'+esc(car.vin||'未填写')+'</strong></div><div><small>备注</small><strong>'+esc(car.note||'无备注')+'</strong></div></div></section><div class="stats detail-stats">'+[['累计收入',income],['累计支出',expense],['收支差额',income-expense]].map(([label,value])=>'<div class="stat"><span class="muted">'+label+'</span><strong>¥ '+money(value)+'</strong></div>').join('')+'</div><section><div class="toolbar"><h2>单车收支明细</h2><span class="section-note">仅显示当前车辆</span><input id="start" type="date" aria-label="开始日期" onchange="renderVehicleEntries()"><span>至</span><input id="end" type="date" aria-label="结束日期" onchange="renderVehicleEntries()"><button class="text-button" onclick="clearFilters()">清空筛选</button></div><p id="subtotal"></p><div class="scroll"><table class="vehicle-entries"><thead><tr>'+['日期','收支','项目','金额','起点 → 终点','往来方','操作'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody id="vehicleEntries"></tbody></table></div><p class="help">收支差额为已录入收入减支出，不代表会计利润。</p></section>';
 $('start').value=from;$('end').value=to;installLedgerCalendar();installProjectHeaderFilter();installKindHeaderFilter();installRouteHeaderFilters();renderProjectFilters();renderVehicleEntries();
}
let currentVehicleRows=[];
let vehicleDateAscending=false;
let vehiclePage=1,vehiclePageSize=20;
function renderVehicleEntries(keepPage=false){
 if(!keepPage)vehiclePage=1;
 const all=ledgerScope(),from=$('start').value,to=$('end').value;
 const rows=all.filter(e=>(page!=='/entries'||ledgerVehicleSelection===null||ledgerVehicleSelection.has(String(e.car_id)))&&(!from||e.date>=from)&&(!to||e.date<=to)&&(vehicleKindSelection===null||vehicleKindSelection.has(e.kind))&&(vehicleProjectSelection===null||vehicleProjectSelection.has(projectKey(e)))&&routeMatches(e)).sort((a,b)=>vehicleDateAscending?(a.date.localeCompare(b.date)||a.id-b.id):(b.date.localeCompare(a.date)||b.id-a.id));
 updateVehicleDateHeader();
 currentVehicleRows=rows;
 const pageCount=Math.max(1,Math.ceil(rows.length/vehiclePageSize));vehiclePage=Math.min(vehiclePage,pageCount);
 const pageRows=rows.slice((vehiclePage-1)*vehiclePageSize,vehiclePage*vehiclePageSize);
 const income=sum(rows,'收入'),expense=sum(rows,'支出');
 $('subtotal').textContent=from&&to&&from>to?'开始日期不能晚于结束日期':`当前筛选 ${rows.length} 笔 · 收入 ¥${money(income)} · 支出 ¥${money(expense)} · 差额 ¥${money(income-expense)}`;
 $('vehicleEntries').innerHTML=pageRows.map(e=>`<tr><td>${esc(e.date)}</td><td><span class="badge ${e.kind==='收入'?'income':'expense'}">${esc(e.kind)}</span></td><td>${esc(e.category)}</td><td class="amount ${e.kind==='收入'?'income':'expense'}">${e.kind==='收入'?'+':'−'}${money(e.cents)}</td><td>${esc(e.start_address)||'未记录'} → ${esc(e.end_address)||'未记录'}</td><td>${esc(e.party)||'—'}</td><td><button type="button" class="secondary" onclick="editLedgerEntry(${e.id})">编辑</button></td>${page==='/entries'?`<td><a class="vehicle-link" href="#/cars/${e.car_id}" title="查看车辆资料与收支明细">${esc(vehicleLabel(data.cars.find(c=>c.id===e.car_id)))}</a></td>`:''}</tr>`).join('')||`<tr><td colspan="${page==='/entries'?8:7}" class="empty">${all.length?'没有符合筛选条件的账目。 <button class="text-button" onclick="clearFilters()">清空筛选</button>':'该车辆暂无收支记录。 <button onclick="entryForm()">记一笔账</button>'}</td></tr>`;
 renderVehiclePagination(rows.length,pageCount);
 renderVehicleTotals(income,expense);
 if(page==='/entries'){
  const table=document.querySelector('.vehicle-entries');table.classList.add('all-ledger-table');
  const header=table.querySelector('thead tr');if(header.lastElementChild?.textContent==='车辆')header.insertBefore(header.lastElementChild,header.children[1]);
  installLedgerVehicleFilter();
  table.querySelectorAll('tbody tr').forEach(row=>{if(row.cells.length===8)row.insertBefore(row.lastElementChild,row.children[1])});
 }
 refreshTables();
}
document.querySelector('#cars')?.closest('section').setAttribute('id','vehicle-list');

let regionSelection=null,regionContext=null,regionRequest=0;
function closeRegion(){regionRequest++;$('regionModal').close()}
function openRegion(side=null,id=null){regionContext={side,id};regionSelection=null;$('regionSearch').value='';$('regionTrail').textContent='';$('regionError').textContent='';$('regionConfirm').disabled=true;$('regionConfirm').textContent=side?'使用此地区':'保存到常用地区';$('regionModal').showModal();openRegionTree()}
async function regionFetch(params){let token=++regionRequest;$('regionItems').textContent='正在加载…';try{let r=await service.request('/api/regions?'+new URLSearchParams(params));if(!r.ok)throw Error();let result=await r.json();if(token!==regionRequest)return;regionRows(result.items)}catch{if(token===regionRequest)$('regionItems').innerHTML='<p>加载失败，请重试。</p><button onclick="regionChildren(\'\')">重新加载</button>'}}
const regionCache=new Map(),regionNodes=new Map();
let regionTreeGeneration=0,regionSearchTimer;
async function regionChildData(parent){if(regionCache.has(parent))return regionCache.get(parent);let r=await service.request('/api/regions?'+new URLSearchParams({parent}));if(!r.ok)throw Error('地区加载失败');let {items}=await r.json();items.forEach(n=>regionNodes.set(n.code,n));regionCache.set(parent,items);return items}
function regionNodeMarkup(r){let selected=regionSelection?.code===r.code;return r.has_children?`<li><details data-code="${r.code}" ontoggle="expandRegionNode(this)"><summary><button type="button" class="region-name ${selected?'is-selected':''}" data-select-code="${r.code}" onclick="event.preventDefault();selectRegion('${r.code}')">${esc(r.name)}<span>${['','省级','城市','区县','乡镇/街道'][r.level]}</span></button></summary><ul class="region-children"><li class="help">展开后加载…</li></ul></details></li>`:`<li><button type="button" class="region-name region-leaf ${selected?'is-selected':''}" data-select-code="${r.code}" onclick="selectRegion('${r.code}')">${esc(r.name)}<span>乡镇/街道</span></button></li>`}
async function openRegionTree(){let generation=++regionTreeGeneration;$('regionItems').innerHTML='<p class="help">正在加载地区树…</p>';$('regionItems').classList.add('tree-container');try{let items=await regionChildData('');if(generation!==regionTreeGeneration)return;$('regionItems').innerHTML='<div id="regionSearchResults" hidden></div><ul id="regionTree" class="region-tree" aria-label="行政区划层级列表">'+items.map(regionNodeMarkup).join('')+'</ul>';$('regionTrail').innerHTML='<span class="help">点击箭头展开，点击名称选中；可在城市、区县或乡镇停止。</span><button class="text-button" onclick="collapseRegionTree()">收起全部</button>'}catch{$('regionItems').innerHTML='<p>地区树加载失败。</p><button onclick="openRegionTree()">重试</button>'}}
async function expandRegionNode(el){if(!el.open||el.dataset.loaded)return;let box=el.querySelector(':scope > ul');box.innerHTML='<li class="help">正在加载…</li>';try{let items=await regionChildData(el.dataset.code);box.innerHTML=items.map(regionNodeMarkup).join('');el.dataset.loaded='1'}catch{box.innerHTML='<li><button class="text-button" onclick="expandRegionNode(this.closest(\'details\'))">加载失败，点击重试</button></li>'}}
function selectRegion(code){let r=regionNodes.get(code);if(!r)return;regionSelection=r;document.querySelectorAll('[data-select-code]').forEach(b=>{let chosen=b.dataset.selectCode===code;b.classList.toggle('is-selected',chosen);b.setAttribute('aria-pressed',String(chosen))});$('regionTrail').innerHTML='<div><small>已选择</small><br><strong>'+esc(r.path)+'</strong></div><button class="text-button" onclick="collapseRegionTree()">收起全部</button>';$('regionConfirm').disabled=r.level<2;$('regionError').textContent=r.level<2?'省级地区仅用于展开，请选择城市、区县或乡镇/街道。':''}
function collapseRegionTree(){document.querySelectorAll('#regionTree details[open]').forEach(d=>d.open=false)}
function regionChildren(){openRegionTree()}
function searchRegions(){clearTimeout(regionSearchTimer);let q=$('regionSearch').value.trim();let token=++regionRequest;let results=$('regionSearchResults'),tree=$('regionTree');if(!results||!tree)return;if(!q){results.hidden=true;tree.hidden=false;return}results.hidden=false;tree.hidden=true;results.innerHTML='<p class="help">正在搜索…</p>';regionSearchTimer=setTimeout(async()=>{try{let r=await service.request('/api/regions?'+new URLSearchParams({q}));if(!r.ok)throw Error();let {items}=await r.json();if(token!==regionRequest)return;items.forEach(n=>regionNodes.set(n.code,n));results.innerHTML=items.map(r=>`<div class="region-option"><button class="text-button" onclick="locateRegion('${r.code}')">${esc(r.name)}<small>${esc(r.path)}</small><small>定位到地区树 ›</small></button></div>`).join('')||'<p class="help">没有匹配地区，试试省、市和区县组合搜索。</p>';if(items.length===100)results.insertAdjacentHTML('beforeend','<p class="help">显示前100项，请补充上级地区关键词。</p>')}catch{if(token===regionRequest)results.textContent='搜索失败，请重新输入关键词重试。'}},180)}
async function locateRegion(code){try{let r=regionNodes.get(code),chain=[];while(r){chain.unshift(r.code);if(!r.parent)break;if(!regionNodes.has(r.parent)){let parentCode=r.parent;let length=parentCode.length;await regionChildData(length===2?'':parentCode.slice(0,length===4?2:4))}r=regionNodes.get(r.parent)}$('regionSearch').value='';$('regionSearchResults').hidden=true;$('regionTree').hidden=false;for(let parent of chain.slice(0,-1)){let el=document.querySelector(`#regionTree details[data-code="${parent}"]`);if(el){await expandRegionNodeData(el);el.open=true}}selectRegion(code);let btn=document.querySelector(`#regionTree [data-select-code="${code}"]`);btn?.scrollIntoView({block:'center'});btn?.focus()}catch{$('regionError').textContent='定位失败，请重新搜索或展开地区树。'}}
async function expandRegionNodeData(el){if(el.dataset.loaded)return;let items=await regionChildData(el.dataset.code);el.querySelector(':scope > ul').innerHTML=items.map(regionNodeMarkup).join('');el.dataset.loaded='1'}
async function confirmRegion(){if(!regionSelection||regionSelection.level<2)return;let {side,id}=regionContext;$('regionConfirm').disabled=true;$('regionError').textContent='';try{let existing=data.addresses.find(a=>a.active&&a.region_code===regionSelection.code);let target=existing;if(!existing||id){let r=await service.request('/api/addresses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({region_code:regionSelection.code,...(id?{id}:{})})});let result=await r.json();if(!r.ok)throw Error(result.error);let fresh=await service.request('/api/data');if(!fresh.ok)throw Error('已保存，刷新失败，请重试');data=await fresh.json();target=data.addresses.find(a=>a.active&&a.region_code===regionSelection.code)}if(side){$('form').elements[side+'_address'].value=addressLabel(target);syncRoute()}else renderAddresses();closeRegion();notify(side?'地区已选择并加入常用':'常用地区已保存')}catch(e){$('regionError').textContent=e.message||'保存失败，请重试'}finally{$('regionConfirm').disabled=false}}
addressForm=function(id){openRegion(null,id)};
renderAddresses=function(){document.querySelector('main').innerHTML='<p id="message" role="status"></p><section><div class="toolbar"><h2>全国行政区划</h2><button onclick="openRegion()">浏览省 / 市 / 区县 / 乡镇</button></div><p class="help">基础库只读，选择地区可加入常用。数据版本：2023-06-30，覆盖大陆31个省级地区，不含港澳台；不代表最新区划。</p></section><section><div class="toolbar"><h2>常用地区</h2><input id="addressSearch" placeholder="搜索常用地区" oninput="renderAddressRows()"><button onclick="openRegion()">＋ 添加常用地区</button></div><p class="help">修改或移除常用地区不影响基础库与历史路线。旧自定义地址保留供历史兼容。</p><table><thead><tr><th>地区 / 原地址</th><th>说明</th><th>操作</th></tr></thead><tbody id="addressRows"></tbody></table></section>';renderAddressRows()};
renderAddressRows=function(){let q=$('addressSearch').value.toLowerCase();$('addressRows').innerHTML=data.addresses.filter(a=>a.active&&addressLabel(a).toLowerCase().includes(q)).map(a=>`<tr><td>${esc(a.name)}</td><td>${a.region_code?'行政区划常用地区':'旧自定义地址 · '+esc(a.detail)}</td><td><button onclick="addressForm(${a.id})">修改</button><button class="danger" onclick="removeAddress(${a.id})">移除常用</button></td></tr>`).join('')||'<tr><td colspan="3" class="empty">暂无常用地区，请从全国基础库添加。</td></tr>';refreshTables()};
function colorBalances(){
 const apply=(el,value)=>{if(!el)return;el.style.color=value>0?'#148365':value<0?'#bf6630':'var(--muted)'};
 const car=data.cars.find(c=>c.id===detailId);
 if(detailId!==null&&car){const rows=ledgerScope();apply(document.querySelector('.detail-stats .stat:last-child strong'),sum(rows,'收入')-sum(rows,'支出'))}
 else if(page==='/'||page==='/cars'||page==='/entries'){apply(document.querySelector('#stats .stat:last-child strong'),sum(vehicleOverviewEntries(),'收入')-sum(vehicleOverviewEntries(),'支出'));document.querySelectorAll('#cars tr').forEach(tr=>{if(tr.cells.length<6)return;const value=Number(tr.cells[4].textContent.replace(/,/g,''));apply(tr.cells[4],value)})}
}
const balanceRender=render;render=function(){balanceRender();colorBalances()};
const balanceDetailRender=renderVehicleDetail;renderVehicleDetail=function(){balanceDetailRender();colorBalances()};
function arrangeWorkspace(){
 if(detailId!==null||!['/','/cars','/entries'].includes(page))return;
 const ledger=page==='/entries';
 $('ledger-section').hidden=!ledger;
 $('vehicle-list').hidden=ledger;
 document.querySelector('.header-actions').innerHTML=ledger?'<button onclick="entryForm()">＋ 记一笔账</button>':'<button onclick="carForm()">＋ 新增车辆</button>';
 document.querySelector('header small').textContent=ledger?'查询收支明细，核对每一笔账目':'管理车辆资料，查看单车经营收支';
}
arrangeWorkspace();installVehicleOverviewDates();if(page==='/'||page==='/cars'){installLedgerVehicleFilter();}

function vehicleProjects(){const projects=new Map();ledgerScope().forEach(e=>projects.set(projectKey(e),e));return [...projects.entries()].sort((a,b)=>a[1].kind.localeCompare(b[1].kind)||a[1].category.localeCompare(b[1].category,'zh-CN'))}
function renderProjectFilters(){if(!$('projectChoices'))return;updateProjectHeader();let projects=vehicleProjects();$('projectChoices').innerHTML='<button type="button" class="project-all '+(vehicleProjectSelection===null?'selected':'')+'" aria-pressed="'+(vehicleProjectSelection===null)+'" onclick="allVehicleProjects()">全部项目</button>'+projects.map(([key,e])=>`<label class="project-chip"><input type="checkbox" value="${esc(key)}" ${vehicleProjectSelection===null||vehicleProjectSelection.has(key)?'checked':''} onchange="toggleVehicleProject(this)"><span>${esc(e.category)}<small>${esc(e.kind)}</small></span></label>`).join('');if(!projects.length)$('projectChoices').insertAdjacentHTML('beforeend','<span class="help">暂无可筛选项目</span>')}
function allVehicleProjects(){vehicleProjectSelection=vehicleProjectSelection===null?new Set():null;renderProjectFilters();renderVehicleEntries()}
function toggleVehicleProject(input){if(vehicleProjectSelection===null)vehicleProjectSelection=new Set(vehicleProjects().map(([key])=>key));if(input.checked)vehicleProjectSelection.add(input.value);else vehicleProjectSelection.delete(input.value);if(vehicleProjectSelection.size===vehicleProjects().length)vehicleProjectSelection=null;renderProjectFilters();renderVehicleEntries()}

function installProjectHeaderFilter(){
 const header=document.querySelector('.vehicle-entries th:nth-child(3)');
 header.innerHTML='<button type="button" class="project-header-button" onclick="openProjectFilter(this)" aria-haspopup="dialog" aria-expanded="false" aria-controls="projectPopover">项目 ▾</button>';
 $('subtotal').insertAdjacentHTML('beforebegin','<div id="projectPopover" popover aria-label="项目筛选" role="dialog"><div class="filter-popover-head"><strong>筛选项目</strong><button type="button" class="text-button" onclick="document.getElementById(\'projectPopover\').hidePopover()" aria-label="关闭项目筛选">×</button></div><p class="help">勾选一个或多个项目组合查看</p><div id="projectChoices"></div></div>');
 const toolbar=document.querySelector('.vehicle-entries').closest('section').querySelector('.toolbar');
 toolbar.insertAdjacentHTML('beforeend','<button class="project-header-button mobile-project-filter" onclick="openProjectFilter(this)" aria-haspopup="dialog" aria-expanded="false" aria-controls="projectPopover">项目 ▾</button>');
 $('projectPopover').addEventListener('toggle',e=>document.querySelectorAll('[aria-controls="projectPopover"]').forEach(b=>b.setAttribute('aria-expanded',String(e.newState==='open'))));
}
function updateProjectHeader(){const text=vehicleProjectSelection===null?'项目 ▾':`项目（${vehicleProjectSelection.size}） ▾`;document.querySelectorAll('[aria-controls="projectPopover"]').forEach(b=>{b.textContent=text;b.classList.toggle('is-filtered',vehicleProjectSelection!==null)})}
function openProjectFilter(button){const panel=$('projectPopover');if(panel.matches(':popover-open')){panel.hidePopover();return}panel.showPopover();const rect=button.getBoundingClientRect();const width=panel.getBoundingClientRect().width;panel.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';panel.style.top=Math.max(12,Math.min(rect.bottom+8,innerHeight-panel.getBoundingClientRect().height-12))+'px'}

function renderVehicleTotals(income,expense){
 let footer=$('vehicleTotals');if(!footer){document.querySelector('.vehicle-entries').closest('.scroll').insertAdjacentHTML('afterend','<div id="vehicleTotals" class="ledger-totals" aria-live="polite"></div>');footer=$('vehicleTotals')}
 let balance=income-expense;
 footer.innerHTML=`<div class="totals-label">当前明细合计 <small>${currentVehicleRows.length} 笔</small></div><div><span>收入</span><strong class="income">+¥${money(income)}</strong></div><div><span>支出</span><strong class="expense">−¥${money(expense)}</strong></div><div><span>差额</span><strong class="${balance>0?'income':balance<0?'expense':'muted'}">${balance>0?'+':balance<0?'−':''}¥${money(Math.abs(balance))}</strong></div><button type="button" onclick="exportVehicleRows()">导出当前明细</button>`;
}
async function exportVehicleRows(){if(!currentVehicleRows.length){await alertDialog('当前没有可导出的收支明细，请先记账或调整筛选条件。');return}try{const car=data.cars.find(c=>c.id===detailId);const result=await service.call('export_ledger',{ids:currentVehicleRows.map(e=>e.id),filename:(detailId===null?'All-vehicles':vehicleLabel(car))+'-收支明细.xlsx'});if(!result.cancelled)notify('Excel明细已导出：'+result.path)}catch(e){notify('导出失败：'+String(e))}}

function updateVehicleDateHeader(){const th=document.querySelector('.vehicle-entries th:first-child');if(!th)return;th.setAttribute('aria-sort',vehicleDateAscending?'ascending':'descending');th.innerHTML=`<button type="button" class="project-header-button" onclick="toggleVehicleDateSort()" aria-label="日期排序，当前${vehicleDateAscending?'由早到晚':'由晚到早'}，点击切换">日期 ${vehicleDateAscending?'↑':'↓'}</button>`}
function toggleVehicleDateSort(){vehicleDateAscending=!vehicleDateAscending;renderVehicleEntries()}

function installKindHeaderFilter(){
 document.querySelector('.vehicle-entries th:nth-child(2)').innerHTML='<button type="button" class="project-header-button" onclick="openKindFilter(this)" aria-haspopup="dialog" aria-expanded="false" aria-controls="kindPopover">收支 ▾</button>';
 $('subtotal').insertAdjacentHTML('beforebegin','<div id="kindPopover" popover role="dialog" aria-label="收支筛选"><div class="filter-popover-head"><strong>筛选收支</strong><button class="text-button" onclick="document.getElementById(\'kindPopover\').hidePopover()" aria-label="关闭收支筛选">×</button></div><div id="kindChoices"></div></div>');
 document.querySelector('.vehicle-entries').closest('section').querySelector('.toolbar').insertAdjacentHTML('beforeend','<button class="project-header-button mobile-project-filter" onclick="openKindFilter(this)" aria-haspopup="dialog" aria-expanded="false" aria-controls="kindPopover">收支 ▾</button>');
 $('kindPopover').addEventListener('toggle',e=>document.querySelectorAll('[aria-controls="kindPopover"]').forEach(b=>b.setAttribute('aria-expanded',String(e.newState==='open'))));renderKindFilters();
}
function renderKindFilters(){if(!$('kindChoices'))return;const all=vehicleKindSelection===null;$('kindChoices').innerHTML=`<button class="project-all ${all?'selected':''}" aria-pressed="${all}" onclick="toggleAllKinds()">全部收支</button>`+['收入','支出'].map(kind=>`<label class="project-chip"><input type="checkbox" value="${kind}" ${all||vehicleKindSelection.has(kind)?'checked':''} onchange="toggleKind(this)"><span class="${kind==='收入'?'income':'expense'}">${kind}</span></label>`).join('');document.querySelectorAll('[aria-controls="kindPopover"]').forEach(b=>{b.textContent=all?'收支 ▾':vehicleKindSelection.size?[...vehicleKindSelection].join('、')+' ▾':'收支（0） ▾';b.classList.toggle('is-filtered',!all)})}
function toggleAllKinds(){vehicleKindSelection=vehicleKindSelection===null?new Set():null;renderKindFilters();renderVehicleEntries()}
function toggleKind(input){if(vehicleKindSelection===null)vehicleKindSelection=new Set(['收入','支出']);if(input.checked)vehicleKindSelection.add(input.value);else vehicleKindSelection.delete(input.value);if(vehicleKindSelection.size===2)vehicleKindSelection=null;renderKindFilters();renderVehicleEntries()}
